LANGS = ["en", "ru", "uk", "de", "fr", "es", "it", "pt", "pl", "tr"]

out = {lang: {} for lang in LANGS}
for key, values in STRINGS.items():
    if len(values) != len(LANGS):
        raise SystemExit(f"{key}: {len(values)} translations, {len(LANGS)} languages expected")
    marks = sorted(re.findall(r"\{[a-z]+\}", values[0]))
    for lang, value in zip(LANGS, values):
        if sorted(re.findall(r"\{[a-z]+\}", value)) != marks:
            raise SystemExit(f"{key}/{lang}: the placeholders {marks} did not survive the translation")
        out[lang][key] = value

body = ["// Generated by tools/make-dsmui-i18n.py — do not edit by hand.",
        "//",
        "// The screen inside DSM is a plain page with no build step, so its",
        "// dictionary is generated and committed. English is the source of truth and",
        "// the fallback: a language without a string shows the English one, never a key.",
        "window.DSMMINI_I18N = " + json.dumps(out, ensure_ascii=False, indent=2) + ";", ""]

path = pathlib.Path(__file__).resolve().parent.parent / "spk" / "ui" / "i18n.js"
path.write_text("\n".join(body), encoding="utf-8")
print(f"{path}: {len(STRINGS)} strings x {len(LANGS)} languages")

# The message a fresh installation leaves for Package Center, which shows what
# postinst writes into SYNOPKG_TEMP_LOGFILE in a box once the installation is
# done. The script picks its line by SYNOPKG_DSM_LANGUAGE, whose values are
# DSM's language codes; DSM has no Ukrainian, so that line is not needed.
DSM_CODES = {"en": "enu", "ru": "rus", "de": "ger", "fr": "fre", "es": "spn",
             "it": "ita", "pt": "ptb", "pl": "plk", "tr": "trk"}
lines = [f"{DSM_CODES[lang]}|{out[lang]['installed']}" for lang in LANGS if lang in DSM_CODES]
installed = path.parent / "installed.txt"
installed.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"{installed}: {len(lines)} languages")
